// Plätze automatisch nach Datum: am 1. jedes Monats wieder ${plaetzeGesamt} frei,
// dann gleichmäßig weniger bis zum Monatsende (mindestens "rest" bleiben frei).
(function () {
  const a = window.LP.aktion, d = new Date();
  const tage = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  const rest = 4;
  const weg = Math.round(((d.getDate() - 1) / (tage - 1)) * (a.plaetzeGesamt - rest));
  a.plaetzeFrei = Math.max(rest, a.plaetzeGesamt - weg);
  a.monat = d.toLocaleString("de-DE", { month: "long" });
})();
